    {
      "fieldName": "ucinn_ascendv2__Transaction_Timeout_Limit__c",
      "toolTip": "The time in seconds to wait for a response from the payment processor. The minimum is 1 second and the maximum is 120 seconds.",
      "customFieldParams": {
        "type": "number",
        "label": "Transaction Timeout Limit"
      }
    },
    {
      "fieldName": "BLANK_Transaction_Timeout_Limit"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Currency_Code__c",
      "required": true,
      "customFieldParams": {
        "type": "text",
        "label": "Currency Code"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Currency_Decimal_Places__c",
      "customFieldParams": {
        "type": "number",
        "label": "Currency Decimal Places"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Gateway_Named_Credential_Name__c",
      "required": true,
      "customFieldParams": {
        "type": "text",
        "label": "Gateway Named Credential Name"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Payment_Gateway__c",
      "required": true,
      "customFieldParams": {
        "type": "picklist",
        "customPicklistValuesString": [
          "CyberSource",
          "Stripe",
          "Spreedly",
          "TouchNet"
        ],
        "label": "Payment Gateway"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Credit_Card_Obfuscation__c",
      "toolTip": "Determines the level of masking on credit card values within stored XML requests.",
      "customFieldParams": {
        "type": "picklist",
        "customPicklistValuesString": [
          "Show First 4 Digits",
          "Show Last 4 Digits",
          "Hide All Digits"
        ],
        "label": "Credit Card Obfuscation"
      }
    },
    {
      "fieldName": "BLANK_CC_OBFUSCATION"
    }
  ],
  [
    {
      "fieldName": "HEADER_CYBERSOURCE_SPREEDLY",
      "toolTip": "Determines the level of masking on credit card values within stored XML requests.",
      "customFieldParams": {
        "type": "header",
        "label": "Cybersource & Spreedly Settings"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Automated_Payment_Retry_Maximum__c",
      "toolTip": "The maximum number of times a failed automated payment can be retried",
      "customFieldParams": {
        "type": "number",
        "label": "Automated Payment Retry Maximum"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Daily_Report_Name__c",
      "toolTip": "Name of report to retrieve daily.",
      "customFieldParams": {
        "type": "text",
        "label": "Daily Report Name"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Automated_Payment_Retry_Weekdays__c",
      "toolTip": "Dictates the days of the week that automated payments are allowed to commence on. Represented as a JSON list of weekday names.",
      "customFieldParams": {
        "type": "text",
        "label": "Automated Payment Retry Weekdays"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Reporting_Named_Credential_Name__c",
      "toolTip": "Credential prefix used for the reporting API.",
      "customFieldParams": {
        "type": "text",
        "label": "Reporting Credential Name"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Email_Reporting__c",
      "toolTip": "Enables email reporting on automated recurring gift/installment payment processing jobs.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Email Reporting"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Reporting_Batch_Size__c",
      "toolTip": "Specifies the batch size for fetching reports from the external payment gateway, and creating review transactions.",
      "customFieldParams": {
        "type": "number",
        "label": "Reporting Batch Size"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Email_Reporting_Primary_Recipient__c",
      "toolTip": "If Email Reporting is enabled, reports will be sent TO this email address.\nExample value: \n\nexample@example.com",
      "customFieldParams": {
        "type": "text",
        "label": "Email Reporting Primary Recipient"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Report_Batch_Hour_Differential__c",
      "toolTip": "How many hours after end of day will this report run. Necessary for us to retrieve reports from the correct date.",
      "customFieldParams": {
        "type": "number",
        "label": "Report Batch Hour Differential"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Email_Reporting_CC_Recipients__c",
      "toolTip": "If Email Reporting is enabled, reports will be CCed to these email addresses. Enter one email address per line.\n\nExample value:\n\nexample1@example.com\nexample2@example.com",
      "customFieldParams": {
        "type": "textarea",
        "label": "Email Reporting CC Recipients"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Update_Payment_Summary_Batch_Size__c",
      "toolTip": "Specifies batch size to update giving summary after retrieving reports and creating review transactions.",
      "customFieldParams": {
        "type": "number",
        "label": "Update Payment Summary Batch Size"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Email_Reporting_ReplyTo_Address__c",
      "toolTip": "If email reporting is enabled, this value will be used as the ReplyTo address for reports.",
      "customFieldParams": {
        "type": "text",
        "label": "Email Reporting ReplyTo Address"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Retry_Failed_Report_Retrieval__c",
      "toolTip": "Each time the report retrieval batch runs, it will retry report retrievals that failed previously, up to a cap.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Retry Failed Report Retrieval"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__WSDL_Version__c",
      "customFieldParams": {
        "type": "text",
        "label": "WSDL Version"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Number_Of_Previous_Failure_Retries__c",
      "toolTip": "Specifies the number of days previous to the original report date where batch failures will be retried up to.",
      "customFieldParams": {
        "type": "number",
        "label": "Number Of Previous Failure Retries"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Is_Retrieve_Orphan_Payments_V2_Enabled__c",
      "toolTip": "Allow creation of orphan payment rtv2 records for reporting if they do not have a matching opportunity.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Is Retrieve Orphan Payments V2 Enabled"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Review_Transaction_Record_Type__c",
      "toolTip": "Record type API name of review transactions created when retrieving transactions from this payment gateway.",
      "customFieldParams": {
        "type": "text",
        "label": "Review Transaction Record Type"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Merchant_ID__c",
      "toolTip": "Currently used by Cybersource to delineate between customers.",
      "customFieldParams": {
        "type": "text",
        "label": "Merchant ID"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Review_Transaction_Record_Type_Namespace__c",
      "toolTip": "Namespace of review transaction record type.",
      "customFieldParams": {
        "type": "text",
        "label": "Review Transaction Record Type Namespace"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Merchant_Defined_Data_Field_Index__c",
      "toolTip": "Merchant defined data field to send payment transaction type to cybersource. Leave blank to not send transaction type.",
      "customFieldParams": {
        "type": "text",
        "label": "Merchant Defined Data Field Index"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Review_Transaction_Record_Type_Prefix__c",
      "toolTip": "Either populate this field or the Review Transaction Record Type/Review Transaction Record Type Namespace field pair. Allows one to specify the default record type for review transactions incoming from the external payment gateway.",
      "customFieldParams": {
        "type": "text",
        "label": "Review Transaction Record Type Prefix"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Use_Reporting_V2__c",
      "toolTip": "Use reporting V2 as opposed to V1.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Reporting V2"
      }
    },
    {
      "fieldName": "BLANK_USE_REPORTING_v2"
    }
  ]
]

